"""Generate a branch-free CIOS Montgomery multiply for P-256 in Xtensa asm
(carries by `saltu`, the reduction from the modulus' shape). Emits the Rust
function text; used by the probe's A/B and, if it wins, by vendored p256."""

PW = [0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0, 0, 0, 1, 0xFFFFFFFF]


def asm_lines():
    L = []
    e = L.append
    e('movi {z}, 0')
    for i in range(8):
        e(f'l32i {{bi}}, {{pb}}, {4 * i}')
        e('movi {c}, 0')
        for j in range(8):
            e(f'l32i {{aj}}, {{pa}}, {4 * j}')
            e(f'l32i {{tj}}, {{pt}}, {4 * j}')
            e('mull {lo}, {aj}, {bi}')
            e('muluh {hi}, {aj}, {bi}')
            e('add {lo}, {lo}, {tj}')       # + t[j]
            e('saltu {c1}, {lo}, {tj}')
            e('add {hi}, {hi}, {c1}')
            e('add {lo}, {lo}, {c}')        # + carry in
            e('saltu {c1}, {lo}, {c}')
            e('add {c}, {hi}, {c1}')
            e(f's32i {{lo}}, {{pt}}, {4 * j}')
        # t8 += c, t9 = carry
        e('l32i {tj}, {pt}, 32')
        e('add {lo}, {tj}, {c}')
        e('saltu {t9}, {lo}, {tj}')
        e('s32i {lo}, {pt}, 32')
        # reduction: m = t0; mff = m * (2^32 - 1) = (m - (m != 0)) : (-m)
        e('l32i {m}, {pt}, 0')
        e('neg {aj}, {m}')                  # low word of mff
        e('saltu {c1}, {z}, {m}')           # m != 0
        e('sub {hi}, {m}, {c1}')            # high word of mff
        e('mov {c}, {m}')                   # word 0 carries m
        for j in range(1, 8):
            e(f'l32i {{tj}}, {{pt}}, {4 * j}')
            if PW[j] == 0xFFFFFFFF:
                # w = t[j] + mff + c: low adds, high = mff_hi + carries
                e('add {lo}, {tj}, {aj}')
                e('saltu {c1}, {lo}, {aj}')
                e('add {lo}, {lo}, {c}')
                e('saltu {bi}, {lo}, {c}')
                e('add {c}, {hi}, {c1}')
                e('add {c}, {c}, {bi}')
            elif PW[j] == 1:
                e('add {lo}, {tj}, {m}')
                e('saltu {c1}, {lo}, {m}')
                e('add {lo}, {lo}, {c}')
                e('saltu {bi}, {lo}, {c}')
                e('add {c}, {c1}, {bi}')
            else:
                e('add {lo}, {tj}, {c}')
                e('saltu {c}, {lo}, {c}')
            e(f's32i {{lo}}, {{pt}}, {4 * (j - 1)}')
        # t7 = t8 + c; t8 = t9 + carry
        e('l32i {tj}, {pt}, 32')
        e('add {lo}, {tj}, {c}')
        e('saltu {c1}, {lo}, {c}')
        e('s32i {lo}, {pt}, 28')
        e('add {lo}, {t9}, {c1}')
        e('s32i {lo}, {pt}, 32')
    return L


def rust_fn(name='fe_mul_xtensa', sub_p='sub_p'):
    body = ',\n            '.join(f'"{l}"' for l in asm_lines())
    return f'''/// `fe_mul` in Xtensa asm (round 3): the same CIOS, every carry by `saltu`
/// (set-if-less-than-unsigned) instead of a compare-and-branch, so no
/// branch at all -- faster, and constant-time where LLVM's carries were
/// not. Generated by `gen_asm_mul.py`; held to the Rust CIOS by the tests
/// and, on the chip, by the probe.
#[cfg(target_arch = "xtensa")]
#[allow(unsafe_code)]
fn {name}(a: &Fe, b: &Fe) -> Fe {{
    let mut t = [0u32; 9];
    // SAFETY: reads a[0..8] and b[0..8], reads and writes t[0..9]; the
    // three pointers are to live arrays of those lengths. No stack use,
    // no memory but these.
    unsafe {{
        core::arch::asm!(
            {body},
            pa = in(reg) a.as_ptr(),
            pb = in(reg) b.as_ptr(),
            pt = in(reg) t.as_mut_ptr(),
            z = out(reg) _,
            bi = out(reg) _,
            aj = out(reg) _,
            tj = out(reg) _,
            lo = out(reg) _,
            hi = out(reg) _,
            c = out(reg) _,
            c1 = out(reg) _,
            m = out(reg) _,
            t9 = out(reg) _,
            options(nostack),
        );
    }}
    {sub_p}(&t)
}}
'''


if __name__ == '__main__':
    print(rust_fn())


REGS = {'pa': 2, 'pb': 3, 'pt': 4, 'z': 5, 'bi': 6, 'aj': 7, 'tj': 8, 'lo': 9, 'hi': 10,
        'c': 11, 'c1': 12, 'm': 13, 't9': 14}


def fixed_lines():
    import re
    out = []
    for l in asm_lines():
        if l.startswith('saltu '):
            r, s, t = [REGS[x.strip(' {}')] for x in l[6:].split(',')]
            w = (6 << 20) | (2 << 16) | (r << 12) | (s << 8) | (t << 4)
            out.append(f'.byte 0x{w & 0xFF:02x}, 0x{(w >> 8) & 0xFF:02x}, 0x{(w >> 16) & 0xFF:02x}  // saltu a{r}, a{s}, a{t}')
        else:
            out.append(re.sub(r'\{(\w+)\}', lambda m: f'a{REGS[m.group(1)]}', l))
    return out


def rust_fn_fixed(name='fe_mul_xtensa', sub_p='sub_p'):
    body = ',\n            '.join('"' + l.split('  //')[0] + '"' for l in fixed_lines())
    return f'''/// `fe_mul` in Xtensa asm (round 3): the same CIOS, every carry by `saltu`
/// (set-if-less-than-unsigned, emitted as bytes: LLVM's assembler does not
/// know it, the core has it) instead of a compare-and-branch, so no branch
/// at all -- faster, and constant-time where LLVM's carries were not.
/// Generated by `gen_asm_mul.py`; held to the Rust CIOS by the tests and,
/// on the chip, by the probe.
#[cfg(target_arch = "xtensa")]
#[allow(unsafe_code)]
fn {name}(a: &Fe, b: &Fe) -> Fe {{
    let mut t = [0u32; 9];
    // SAFETY: reads a[0..8] and b[0..8], reads and writes t[0..9]; the
    // three pointers are to live arrays of those lengths. a2-a14 fixed (the
    // `saltu` bytes name them); no stack use, no memory but these.
    unsafe {{
        core::arch::asm!(
            {body},
            in("a2") a.as_ptr(),
            in("a3") b.as_ptr(),
            in("a4") t.as_mut_ptr(),
            out("a5") _,
            out("a6") _,
            out("a7") _,
            out("a8") _,
            out("a9") _,
            out("a10") _,
            out("a11") _,
            out("a12") _,
            out("a13") _,
            out("a14") _,
            options(nostack),
        );
    }}
    {sub_p}(&t)
}}
'''
